DO $$
DECLARE
    CREATED_AT timestamp := now();
    CREATED_BY text := 'Run:ai';

    uuid_model_falcon_7b uuid := 'c6accd0c-3652-4975-ba11-7c9e3e05c7dd';
    uuid_model_falcon_40b uuid := 'b074bd87-6c31-41fa-89f2-16b470d46d29';
    uuid_environment_llm_server uuid := 'a50ef834-4008-4a3a-9ac8-bfc9c177f5e4';
    uuid_compute_gpu_memory_80g uuid := '07e99ad0-aa2f-4dd2-9385-e4a4b2ddc207';

    THUMBNAIL_FALCON_40B bytea := 'data:image/png;base64,';
BEGIN
    BEGIN
        -- order matters, first the assets, then the metadata
        DELETE FROM assets_model WHERE asset_id in
           (select id FROM assets_metadata WHERE kind = 'model' and scope = 'system' and name in
               ('llama-32-1b-instruct',
                'llama-32-3b-instruct',
                'llama-31-8b-instruct',
                'mistral-7b',
                'gemma-2-2b-it',
                'gemma-2-9b-it')
            );

        DELETE FROM assets_metadata WHERE scope = 'system' and (
            (kind = 'model' and name in
                ('llama-32-1b-instruct',
                 'llama-32-3b-instruct',
                 'llama-31-8b-instruct',
                 'mistral-7b',
                 'gemma-2-2b-it',
                 'gemma-2-9b-it'))
            );

        -- revert falcon 7b title update
        UPDATE assets_model
        SET title = 'Falcon Instruct 7B'
        WHERE asset_id = uuid_model_falcon_7b;

        -- revert falcon 40b delete by re-inserting it as before
        INSERT INTO assets_metadata ("id", "kind", "scope", "name", "created_by", "created_at", "updated_by", "updated_at") VALUES
            (uuid_model_falcon_40b, 'model', 'system', 'falcon-40b-instruct', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT);

        INSERT INTO assets_model ("asset_id", "title", "description", "thumbnail", "huggingface_id", "license", "compute_asset_id", "environment_asset_id") VALUES
            (uuid_model_falcon_40b, 'Falcon Instruct 40B',
             'TII''s Falcon generative text model of 40B parameters. Pre-trained, fine-tuned, and optimized for dialog cases.',
             THUMBNAIL_FALCON_40B, 'tiiuae/falcon-40b-instruct', '', uuid_compute_gpu_memory_80g, uuid_environment_llm_server);
    EXCEPTION
        WHEN unique_violation THEN
            -- do nothing, already exists
            RAISE NOTICE 'Assets already exist, skipping';
    END;
END $$;
